/*
 * signed_curvature_reference_golden.h — the committed golden subset of the
 * ADR-0018 reference grid (tests/bridge/signed_curvature_reference_grid_test.cpp).
 *
 * Each row is the binary128 reference rounded to f64 for one (configuration,
 * K) case: every 64th binade of K, the binade edges, and the series-switch
 * neighbourhood. The rows are generated by running the grid test with
 * `--emit-golden signed_curvature_reference_golden.inc` on a build with
 * binary128 arithmetic; that build re-derives every row and fails if the
 * committed file differs by one bit. Builds without binary128 compare the
 * f64 core against these rows.
 */
#ifndef ESHKOL_SIGNED_CURVATURE_REFERENCE_GOLDEN_H
#define ESHKOL_SIGNED_CURVATURE_REFERENCE_GOLDEN_H

struct ScurvGoldenRow {
    int cfg;
    double K;
    int domain_ok, jet_ok, grad_ok;
    double d, d1, d2;
    double g[3];
};

#include "signed_curvature_reference_golden.inc"

static const ScurvGoldenRow kSignedCurvatureGolden[] = { ESHKOL_SCURV_GOLDEN_ROWS };

#endif
